#include <vector>
#include <unordered_set>
#include <algorithm>

class Solution {
public:
    int maxWeight(int n, std::vector<std::vector<int>>& edges, int k, int t) {
        std::vector<std::vector<std::pair<int, int>>> graph(n);
        for (const auto& e : edges) {
            graph[e[0]].push_back({e[1], e[2]});
        }

        std::vector<std::unordered_set<int>> dp(n);
        for (int u = 0; u < n; ++u) dp[u].insert(0);

        for (int step = 0; step < k; ++step) {
            std::vector<std::unordered_set<int>> next_dp(n);
            for (int u = 0; u < n; ++u) {
                for (int s : dp[u]) {
                    for (const auto& edge : graph[u]) {
                        int v = edge.first;
                        int w = edge.second;
                        if (s + w < t) {
                            next_dp[v].insert(s + w);
                        }
                    }
                }
            }
            dp = std::move(next_dp);
        }

        int ans = -1;
        for (int u = 0; u < n; ++u) {
            for (int s : dp[u]) {
                ans = std::max(ans, s);
            }
        }
        return ans;
    }
};

import java.util.*;

class Solution {
    public int maxWeight(int n, int[][] edges, int k, int t) {
        List<int[]>[] graph = new ArrayList[n];
        for (int i = 0; i < n; ++i) graph[i] = new ArrayList<>();
        for (int[] e : edges) {
            graph[e[0]].add(new int[]{e[1], e[2]});
        }

        Set<Integer>[] dp = new HashSet[n];
        for (int i = 0; i < n; ++i) {
            dp[i] = new HashSet<>();
            dp[i].add(0);
        }

        for (int step = 0; step < k; ++step) {
            Set<Integer>[] nextDp = new HashSet[n];
            for (int i = 0; i < n; ++i) nextDp[i] = new HashSet<>();

            for (int u = 0; u < n; ++u) {
                for (int s : dp[u]) {
                    for (int[] edge : graph[u]) {
                        int v = edge[0];
                        int w = edge[1];
                        if (s + w < t) {
                            nextDp[v].add(s + w);
                        }
                    }
                }
            }
            dp = nextDp;
        }

        int ans = -1;
        for (int u = 0; u < n; ++u) {
            for (int s : dp[u]) {
                if (s > ans) ans = s;
            }
        }
        return ans;
    }
}

