var maxWeight = function(n, edges, k, t) {
    const graph = Array.from({ length: n }, () => []);
    for (const [u, v, w] of edges) {
        graph[u].push([v, w]);
    }

    let dp = Array.from({ length: n }, () => new Set([0]));

    for (let step = 0; step < k; ++step) {
        const nextDp = Array.from({ length: n }, () => new Set());
        for (let u = 0; u < n; ++u) {
            for (const s of dp[u]) {
                for (const [v, w] of graph[u]) {
                    if (s + w < t) {
                        nextDp[v].add(s + w);
                    }
                }
            }
        }
        dp = nextDp;
    }

    let ans = -1;
    for (let u = 0; u < n; ++u) {
        for (const s of dp[u]) {
            if (s > ans) ans = s;
        }
    }
    return ans;
};
